# Composes the three market pages from one skeleton. Run: python3 build_pages.py
import json
SKEL = '''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>{title}</title>
<meta name="description" content="{desc}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap">
<link rel="stylesheet" href="corridor.css">
<style>{css}</style>
</head>
<body>
<div id="veil" class="on"></div>
<canvas id="gl" aria-hidden="true"></canvas>
<div class="scrim" id="scrimL" aria-hidden="true"></div><div class="scrim" id="scrimC" aria-hidden="true"></div>
<div class="tip" id="tip" aria-hidden="true"><div class="t"></div><div class="b"></div></div>
<header class="nav"><div class="in">
  <a class="logo" href="index.html" data-page><i></i>Resonance</a>
  <nav><a href="index.html#product" data-page>Platform</a><a href="epc.html" data-page>EPC</a><a href="data-centers.html" data-page>Data centers</a><a href="supply-chain.html" data-page>Supply chain</a></nav>
  <a class="btn primary mag" href="#" data-go="4">Book a working session</a>
</div></header>
<div class="scroller" aria-hidden="true" style="height: 1000vh"></div>
<div class="stage">
<section class="sec hero on" id="hero"><div class="in">
  <div class="kicker layer">{kicker}</div>
  <h1 class="layer" id="h1"></h1>
  <p class="lead layer">{lead}</p>
  <div class="ctas layer"><a class="btn primary mag" href="#" data-go="4">Book a working session</a><a class="btn ghost mag" href="#" data-go="1">See the journey ↓</a></div>
  <span class="sample layer">Sample data · fictional company and project · hover anything in the scene</span>
</div></section>
{rooms}
<section class="sec cta" id="book"><div class="in">
  <div class="eyebrow">{ctaEyebrow}</div>
  <h2>Ninety minutes. Your data stays with you.</h2>
  <div class="ccard" id="ccard">
    <form class="form" onsubmit="return false">
      <div class="row2"><div><label>Work email</label><input placeholder="you@company.com"></div><div><label>Company</label><input placeholder="Company"></div></div>
      <div class="row2"><div><label>Role</label><input placeholder="{rolePh}"></div><div><label>{ctaField}</label><input placeholder="{ctaPh}"></div></div>
      <div class="ctas"><a class="btn primary mag" href="#">Book a working session</a><a class="btn ghost mag" href="index.html" data-page>Back to the platform</a></div>
    </form>
    <p>{ctaLeave} The model never makes the call; a named owner signs.</p>
  </div>
  <div class="foot">Resonance helps operational teams make faster, better decisions with the data they already have.<span class="sample">Sample data on this page is fictional.</span></div>
</div></section>
</div>
<div class="bar" id="bar"><span>Resonance</span><div class="prog"><i id="prog"></i></div><a class="btn primary mag" href="#" data-go="4">Book a working session</a></div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.min.js"></script>
<script src="corridor.js"></script>
<script>
(() => {{
const {{ ss, clamp, lerp, eo, snap, sub, vis, words, OX, OY, PH0, FINE }} = Corridor;
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const LX = PH0 ? 0 : -.6;
words($('#h1'), {h1});
const heroPeel = (q) => {{ const peel = ss(.25, .95, q); $$('.hero .layer').forEach((l, i) => {{ l.style.transform = `translateY(${{-peel * (40 - i * 8)}}px) scale(${{1 + peel * (.5 - i * .1)}})`; l.style.opacity = 1 - ss(.3, .75, q); l.style.filter = `blur(${{peel * 6}}px)`; }}); }};
const CTA = {{ name: 'book', a: .88, b: 1, dom: '#book', selfDom: true, shift: 0, scrim: 'none', cam: {ctaCam}, build() {{}},
  update(q, K, S, el) {{ K.fade = ss(.12, .55, q); const up = ss(.3, .6, q); $('#ccard').style.opacity = up; $('#ccard').style.transform = `translateY(${{(1 - up) * 40}}px) scale(${{lerp(.97, 1, up)}})`; el.style.opacity = ss(.18, .42, q); el.querySelector('.in').style.transform = `translateY(${{(1 - ss(.18, .5, q)) * 30}}px)`; }} }};
{js}
Corridor.start({{ sections: SECTIONS.concat([CTA]), room: 60, hoverDefault: {{ industry: '{ind}', go: 4, goLabel: 'Book a working session' }} }});
}})();
</script>
</body>
</html>
'''
HERO_CSS = '.hero { text-align: left; } .hero .in { max-width: 980px; } .hero h1 { font-size: clamp(38px, 5.6vw, 76px); } .hero .lead { margin-left: 0; } .hero .ctas { justify-content: flex-start; } .kicker { margin-bottom: 18px; opacity: 0; animation: wIn 1s .2s forwards; } .sec .in { max-width: 1180px; } .room .in { display: grid; grid-template-columns: minmax(0, 520px); gap: 18px; align-items: start; } .cta h2 { font-size: clamp(32px, 4.6vw, 60px); } .rec { background: rgba(17,20,27,.7); border: 1px solid var(--rule); border-radius: 8px; padding: 12px 14px; font: 400 12.5px/1.55 var(--mono); color: var(--bone-2); margin-top: 16px; } .rec b { color: var(--bone); font-weight: 500; } .rec .sig { color: var(--ok); } .rec .ln { display: block; overflow: hidden; white-space: nowrap; max-width: 0; } .note { font: 400 12px/1.4 var(--mono); color: var(--mute); margin-top: 10px; } .note b { color: var(--ember); font-weight: 500; }'

PAGES = {}

